
-- Fictional-only fixtures; no ownership inference or hosted execution.
reset role;
insert into public.patients(id,hospital_id,ownership_state,patient_ref,first_name,last_name,identity_status,temporary_identifier)
select ('d3000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'a0000000-0000-0000-0000-000000000001','verified','SYN-PAGE-'||lpad(n::text,4,'0'),null,null,'provisional','TMP-SYN-PAGE-'||n from generate_series(1,80)n;
insert into public.visits(hospital_id,ownership_state,department_id,patient_id,complaint,priority,status,next_action,triage_state,urgency_source)
select 'a0000000-0000-0000-0000-000000000001','verified','a3000000-0000-0000-0000-000000000001',id,null,null,'waiting','assessment','not_yet_triaged','not_assessed' from public.patients where patient_ref like 'SYN-PAGE-%';
set role authenticated;
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select set_config('paged.first',public.necms_read_page('queue','{}',null,1)::text,false);
select pg_temp.assert_true(jsonb_array_length(current_setting('paged.first')::jsonb->'items')=1,'bounded queue');
select pg_temp.assert_true((current_setting('paged.first')::jsonb->>'total')::integer>80,'total counts beyond visible page');
select pg_temp.assert_true((current_setting('paged.first')::jsonb#>>'{summary,unknown_urgency}')::integer>=80,'unknown urgency visible in full-scope summary');
select pg_temp.assert_true((public.necms_read_page('queue','{}',(current_setting('paged.first')::jsonb->>'next_cursor')::uuid,1)#>>'{items,0,encounter,id}')<>(current_setting('paged.first')::jsonb#>>'{items,0,encounter,id}'),'continuation does not duplicate first row');
do $$declare page jsonb; token uuid; identifiers text[]:='{}'; expected integer;begin
loop
 page:=public.necms_read_page('queue','{}',token,7);
 expected:=(page->>'total')::integer;
 select identifiers||coalesce(array_agg(coalesce(value#>>'{work,id}',value#>>'{encounter,id}')),'{}') into identifiers from jsonb_array_elements(page->'items');
 token:=(page->>'next_cursor')::uuid;exit when token is null;
end loop;
perform pg_temp.assert_true(cardinality(identifiers)=expected and cardinality(identifiers)=(select count(distinct x) from unnest(identifiers)x),'all pages have no omissions or duplicate stable IDs');
end $$;
select pg_temp.assert_true((public.necms_read_page('queue','{"q":"no-synthetic-match"}')->>'total')::int=0,'server search narrows results');
select pg_temp.assert_true(public.necms_read_page('queue','{"q":"no-synthetic-match"}')->'summary'=current_setting('paged.first')::jsonb->'summary','empty search does not imply nobody waits');
select pg_temp.assert_true((public.necms_read_page('queue','{"urgency":"unknown"}')->>'total')::int>=80,'unknown filter separate from numerical urgency');
select pg_temp.assert_true((public.necms_read_page('queue','{"triage":"not_yet_triaged"}')->>'total')::int>=80,'server triage filter');
select pg_temp.assert_true((public.necms_read_page('queue','{"department":"a3000000-0000-0000-0000-000000000001"}')->>'total')::int>=80,'department scope applied');
select pg_temp.assert_true((public.necms_read_page('patients','{"q":"TMP-SYN-PAGE-"}')->>'total')::int=80,'provisional identity search supports temporary identifiers');
select pg_temp.assert_true(jsonb_array_length(public.necms_read_page('patients','{}',null,5)->'items')=5,'bounded patient lookup');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''[]'')','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',null)','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{}'',null,0)','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{}'',null,51)','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{}'',null,null)','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{"state":"forged"}'')','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{"urgency":"0"}'')','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{"department":"forged"}'')','22P02');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{"hospital_id":"a0000000-0000-0000-0000-000000000001"}'')','23514');
select pg_temp.expect_error('select public.necms_read_page(''patients'',''{"department":"a3000000-0000-0000-0000-000000000001"}'')','23514');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{"service":"00000000-0000-0000-0000-000000000001"}'')','42501');
select pg_temp.expect_error('select public.necms_read_page(''queue'',''{}'',''00000000-0000-0000-0000-000000000001'')','42501');
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{"q":"changed"}'',%L::uuid,1)',current_setting('paged.first')::jsonb->>'next_cursor'),'40001');
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,2)',current_setting('paged.first')::jsonb->>'next_cursor'),'40001');
select public.necms_read_page('services');select public.necms_read_page('teams');select public.necms_read_page('staff');select public.necms_read_page('reasons');select public.necms_read_page('departments');select public.necms_read_page('resources');
select public.necms_read_page('assessments',jsonb_build_object('encounter',current_setting('coord.low')));
select public.necms_read_page('vitals',jsonb_build_object('encounter',current_setting('coord.low')));
select public.necms_read_page('timeline',jsonb_build_object('encounter',current_setting('coord.low')));
select pg_temp.assert_true((public.necms_read_page('work_events',jsonb_build_object('encounter',current_setting('coord.low')))#>'{items,0,queue_snapshot}')='[]'::jsonb,'event page excludes unbounded evidence array');
select pg_temp.assert_true((public.necms_read_page('evidence',jsonb_build_object('record',current_setting('coord.start')::jsonb->>'id'))->>'total')::int=1,'historical evidence remains available via bounded pages');
select pg_temp.assert_true((public.necms_read_page('annotations',jsonb_build_object('record',current_setting('coord.exception')))->>'total')::int=1,'exception annotations remain accessible');
select pg_temp.expect_error('select public.necms_read_page(''assessments'')','23514');
select pg_temp.assert_true(octet_length(public.necms_read_page('queue','{}',null,5)::text)<50000,'page payload bounded independently of hospital size');
select pg_temp.expect_error('select public.necms_read_revision(''a0000000-0000-0000-0000-000000000001'')','42501');
-- Cursors cannot cross contexts even for a legitimately dual-hospital user.
select pg_temp.act('60000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000001');
select pg_temp.assert_true((public.necms_read_page('patients','{"q":"SYN-PAGE-"}')->>'total')::int=0,'B cannot search A identities');
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,1)',current_setting('paged.first')::jsonb->>'next_cursor'),'42501');
select pg_temp.expect_error(format('select public.necms_read_page(''timeline'',%L::jsonb)',jsonb_build_object('encounter',current_setting('coord.low'))),'42501');
select pg_temp.expect_error(format('select public.necms_read_page(''annotations'',%L::jsonb)',jsonb_build_object('record',current_setting('coord.exception'))),'42501');
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,1)',current_setting('paged.first')::jsonb->>'next_cursor'),'42501');
select set_config('paged.fresh',public.necms_read_page('queue','{}',null,1)::text,false);
reset role;
update public.visits set version=version+1 where id=(current_setting('paged.fresh')::jsonb#>>'{items,0,encounter,id}')::uuid;
set role authenticated;
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,1)',current_setting('paged.fresh')::jsonb->>'next_cursor'),'40001');
select set_config('paged.fresh',public.necms_read_page('queue','{}',null,1)::text,false);
reset role;
update necms_private.read_cursors set expires_at=clock_timestamp()-interval '1 second' where id=(current_setting('paged.fresh')::jsonb->>'next_cursor')::uuid;
set role authenticated;
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,1)',current_setting('paged.fresh')::jsonb->>'next_cursor'),'40001');
select set_config('paged.fresh',public.necms_read_page('queue','{}',null,1)::text,false);
reset role;
delete from public.role_capabilities where role_id='a1000000-0000-0000-0000-000000000001' and capability='queue.read';
set role authenticated;
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,1)',current_setting('paged.fresh')::jsonb->>'next_cursor'),'42501');
reset role;
insert into public.role_capabilities values('a1000000-0000-0000-0000-000000000001','queue.read');
delete from public.role_capabilities where role_id='a1000000-0000-0000-0000-000000000001' and capability='patient.identity.read';
set role authenticated;
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select pg_temp.expect_error('select public.necms_read_page(''exceptions'')','42501');
select pg_temp.expect_error(format('select public.necms_read_page(''annotations'',%L::jsonb)',jsonb_build_object('record',current_setting('coord.exception'))),'42501');
reset role;
insert into public.role_capabilities values('a1000000-0000-0000-0000-000000000001','patient.identity.read');
set role authenticated;
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select set_config('paged.fresh',public.necms_read_page('queue','{}',null,1)::text,false);
reset role;
update public.hospital_memberships set active=false,authorization_version=authorization_version+1 where hospital_id='a0000000-0000-0000-0000-000000000001' and user_id='60000000-0000-0000-0000-000000000001';
set role authenticated;
select pg_temp.expect_error(format('select public.necms_read_page(''queue'',''{}'',%L::uuid,1)',current_setting('paged.fresh')::jsonb->>'next_cursor'),'42501');
